begin;
insert into auth.users(id,email,raw_user_meta_data) select ('a0000000-0000-4000-8000-00000000000'||n)::uuid,'experience'||n||'@example.test',jsonb_build_object('username','experience_'||n) from generate_series(1,2)n;
insert into public.circles(id,creator_id,name,icon) values('a0000000-0000-4000-8000-000000000010','a0000000-0000-4000-8000-000000000001','Orbit crew','rocket');
insert into public.memberships(circle_id,user_id) values('a0000000-0000-4000-8000-000000000010','a0000000-0000-4000-8000-000000000001');
insert into public.challenges(id,circle_id,created_by,rules,rules_hash,status) values('a0000000-0000-4000-8000-000000000011','a0000000-0000-4000-8000-000000000010','a0000000-0000-4000-8000-000000000001','{"title":"Daily orbit","timezone":"UTC","opening":"00:00","cutoff":"23:59","graceDays":1,"penaltyMinor":250,"maxPenaltyMinor":1000,"rewardPolicy":"discipline_v1","gracePolicy":"automatic_v1"}','hash','active');
insert into public.challenge_participants(challenge_id,user_id,status,rules_hash) values('a0000000-0000-4000-8000-000000000011','a0000000-0000-4000-8000-000000000001','accepted','hash');
insert into public.daily_obligations(id,challenge_id,user_id,local_date,deadline_at) select ('a0000000-0000-4000-8000-00000000010'||n)::uuid,'a0000000-0000-4000-8000-000000000011','a0000000-0000-4000-8000-000000000001',current_date-n,clock_timestamp()-interval'1 day'*n from generate_series(1,2)n;
create function pg_temp.assert_ok(value boolean,msg text)returns void language plpgsql as $$begin if value is not true then raise exception '%',msg;end if;end;$$;
create function pg_temp.must_fail(q text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute q;exception when others then failed:=true;end;if not failed then raise exception 'Expected failure: %',q;end if;end;$$;
grant execute on function pg_temp.assert_ok(boolean,text),pg_temp.must_fail(text)to authenticated,anon;
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
do $$declare r jsonb;g jsonb;begin
  r:=public.stakeup_wallet(10000,'a0000000-0000-4000-8000-000000000099');
  perform pg_temp.assert_ok((r->>'balanceMinor')::bigint=10000,'Top-up missing');
  perform pg_temp.assert_ok((r->>'pendingPenaltyMinor')::bigint=250,'Excess missed day did not contribute');
  r:=public.stakeup_wallet(10000,'a0000000-0000-4000-8000-000000000099');
  perform pg_temp.assert_ok((r->>'balanceMinor')::bigint=10000 and jsonb_array_length(r->'entries')=1,'Retry duplicated top-up');
  perform pg_temp.must_fail($q$select public.stakeup_wallet(15000,'a0000000-0000-4000-8000-000000000099')$q$);
  perform pg_temp.must_fail($q$select public.stakeup_wallet(-1,'a0000000-0000-4000-8000-000000000098')$q$);
  perform pg_temp.must_fail('insert into public.wallet_top_ups(user_id,request_id,amount_minor)values(auth.uid(),gen_random_uuid(),100)');
  perform pg_temp.must_fail('select private.effective_grace(''a0000000-0000-4000-8000-000000000011'',auth.uid())');
  update public.profiles set currency='KGS',theme_accent='blue' where id=auth.uid();
  update public.profiles set theme_accent='violet' where id=auth.uid();
  g:=public.stakeup_community('grace_list','{"challengeId":"a0000000-0000-4000-8000-000000000011"}');
  perform pg_temp.assert_ok(jsonb_array_length(g)=1 and g->0->>'obligationId'='a0000000-0000-4000-8000-000000000102','Legacy grace not shown in calendar');
  perform public.stakeup_community('grace_choose','{"challengeId":"a0000000-0000-4000-8000-000000000011","obligationId":"a0000000-0000-4000-8000-000000000102"}');
  r:=public.stakeup_competition('a0000000-0000-4000-8000-000000000011');
  perform pg_temp.assert_ok((r->>'poolMinor')::bigint=250 and jsonb_array_length(r->'ledger')=1,'Pool or pending ledger incorrect');
  perform pg_temp.assert_ok((r->'rows'->0->>'grace')::integer=1 and(r->'rows'->0->>'missed')::integer=1,'Excused day counted as missed');
  perform public.stakeup_competition('a0000000-0000-4000-8000-000000000011',true);
  r:=public.stakeup_wallet();
  perform pg_temp.assert_ok((r->>'balanceMinor')::bigint=10000 and(r->>'pendingPenaltyMinor')::bigint=0 and jsonb_array_length(r->'entries')=3,'Final penalty/refund did not reconcile with wallet');
  perform public.stakeup_competition('a0000000-0000-4000-8000-000000000011',true);
  perform pg_temp.assert_ok(jsonb_array_length(public.stakeup_wallet()->'entries')=3,'Repeated settlement duplicated wallet entries');
  perform set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000002',true);
  r:=public.stakeup_wallet();
  perform pg_temp.assert_ok((r->>'balanceMinor')::bigint=0 and jsonb_array_length(r->'entries')=0,'Wallet leaked between accounts');
  perform pg_temp.assert_ok((select count(*)=0 from public.wallet_top_ups),'Top-ups leaked through RLS');
end;$$;
reset role;
set local role anon;
select pg_temp.must_fail('select public.stakeup_wallet()');
reset role;
rollback;
